        'negócios,',
        forecast[slice].amountInCents / 100,
        forecast.currency,
      );
    }
  }

  const deals = [];
  for (let page = 1; ; page++) {
    const { items, total, size } = await get(`/deals?page=${page}&size=200&sort=close_date`);
    deals.push(...items);
    if (page * size >= total) break;
  }

  const cell = (value) => `"${String(value ?? '').replaceAll('"', '""')}"`;
  const rows = [['negocio', 'conta', 'dono', 'categoria', 'fechamento', 'valor']];
  for (const d of deals) {
    rows.push([
      d.name,
      d.accountName,
      d.ownerName,
      d.forecastCategory,
      d.expectedCloseDate,
      (d.amountInCents ?? 0) / 100,
    ]);
  }
  writeFileSync('forecast.csv', rows.map((row) => row.map(cell).join(',')).join('\n'));
  ```

